mapper.delete:
DELETE FROM attendance_exception_data
WHERE id IN

    #{item}

mapper.select:
select b.id, b.attendance_date attendanceDate, b.actual_start_work_time actualStartWorkTime, b.actual_end_work_time actualEndWorkTime,
b.type, b.exception_id exceptionId, b.create_time createTime, a.name, a.department, a.attendance_month attendanceMonth, a.position
from attendance_exception a
join attendance_exception_data b on a.id = b.exception_id
where a.name = #{name}

    and a.department = #{department}

and b.attendance_date >= #{startDate} and b.attendance_date <= #{endDate}
order by b.attendance_date
